#!/usr/bin/env bash\nset -euo pipefail\n\nSCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/../src" && pwd)\nSCRIPT=\"$SCRIPT_DIR/disk-usage.sh\"\n\n# Create a temporary file with mocked df output.\ncat > /tmp/df_test.txt <<'EOF'\nFilesystem Size Used Avail Use% Mounted on\n/dev/sda1 100G 45G 55G 45% /\ntmpfs 2G 200M 1.8G 10% /run\n/dev/sdb1 200G 180G 20G 90% /data\nEOF\n\n# Run the utility against the mocked data.\noutput=$($SCRIPT /tmp/df_test.txt)\n\nread -r -d '' expected <<'EOT'\n/                     45% [#########-----------]\n/run                  10% [##------------------]\n/data                 90% [##################--]\nEOT\n\nif [[ \"$output\" != \"$expected\" ]]; then\n  echo \"Test failed\"\n  echo \"Got:\"\n  echo \"$output\"\n  echo \"Expected:\"\n  echo \"$expected\"\n  exit 1\nfi\n\necho \"Test passed\"\n
